import{c as t,Q as a,j as o,m as s}from"./chunks/framework.DK3sgdKX.js";const k=JSON.parse('{"title":"TH07 API 调研与引擎能力补齐","description":"","frontmatter":{},"headers":[],"relativePath":"TH07_PORT_AUDIT.md","filePath":"TH07_PORT_AUDIT.md","lastUpdated":1795193770000}'),d={name:"TH07_PORT_AUDIT.md"};function i(c,e,l,r,h,n){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="th07-api-调研与引擎能力补齐" tabindex="-1">TH07 API 调研与引擎能力补齐 <a class="header-anchor" href="#th07-api-调研与引擎能力补齐" aria-label="Permalink to &quot;TH07 API 调研与引擎能力补齐&quot;">​</a></h1><p>本文总结面向东方妖妖梦（TH07）机制移植时的前置引擎调研结论，以及据此补齐的四项通用 Runtime 能力。后续单面移植实践见 <a href="./TH07_STAGE5_PORT">TH07 五面移植说明</a> 与 <a href="./TH07_STAGE6_PORT">TH07 六面移植说明</a>。</p><h2 id="_1-参考项目与数据来源" tabindex="-1">1. 参考项目与数据来源 <a class="header-anchor" href="#_1-参考项目与数据来源" aria-label="Permalink to &quot;1. 参考项目与数据来源&quot;">​</a></h2><p>调研参考了公开社区资料与工具，PySTG 本身不内置或分发任何原作素材和可执行文件：</p><ul><li><a href="https://github.com/some100/th07" target="_blank" rel="noreferrer">some100/th07</a>：TH07 1.00b 匹配反编译参考，用于核对 Player、Enemy、ECL 特殊函数、计时与攻击逻辑。</li><li><a href="https://github.com/AgentMystia/th07_web" target="_blank" rel="noreferrer">AgentMystia/th07_web</a>：辅助对照 SHT、结界与自机数据格式。</li><li><a href="https://github.com/thpatch/thtk" target="_blank" rel="noreferrer">thpatch/thtk</a>（<code>thdat</code> / <code>thecl</code>）：用于离线分析用户本地游戏副本中的 PBG4 档案与 ECL 脚本。</li></ul><h2 id="_2-已确认并补齐的四项引擎能力" tabindex="-1">2. 已确认并补齐的四项引擎能力 <a class="header-anchor" href="#_2-已确认并补齐的四项引擎能力" aria-label="Permalink to &quot;2. 已确认并补齐的四项引擎能力&quot;">​</a></h2><p>初期排查确认了四组会直接阻断 TH07 玩法还原的底层缺口，现均已在通用 Runtime 中实现并接入主循环与独立预览器（示范脚本见 <code>game_content/examples/th07_api.py</code>）：</p><table tabindex="0"><thead><tr><th>原缺口</th><th>问题本质</th><th>当前公开入口与实现</th></tr></thead><tbody><tr><td><strong>玩家受击契约不足</strong></td><td>旧 <code>take_damage()</code> 只返回布尔值，无法区分“被森罗结界吸收”“进入 Deathbomb 救援窗口”和“真正掉命”，容易误记 miss 或破坏符卡捕获判定。</td><td><code>src/game/player/hit.py</code> 引入 <code>PlayerHit</code> / <code>HitDecision</code> / <code>HitResult</code> 与唯一提交点 <code>commit_player_hits</code>；<code>PlayerBase.receive_hit</code> 支持 <code>ignored</code> / <code>handled</code> / <code>pending</code> / <code>rescued</code> / <code>miss</code> 五种状态，捕获失败与 miss/Bomb 计数解耦。</td></tr><tr><td><strong>缺少全系统仿真倍率</strong></td><td>妖梦慢动作（<code>ExInsYoumuSetGameSpeed</code>）会影响玩家、自机弹、敌人、计时器、动画和背景，不只是降低敌弹速度。</td><td><code>TimeControl</code> 新增 0–1 分域仿真倍率，<code>StageContext</code> 暴露 <code>slow_motion()</code>、<code>set_simulation_scale()</code> 与 <code>wait_control()</code>；每控制帧首部统一采样，控制帧/Trace 保持单调，仿真时间支持分数推进。</td></tr><tr><td><strong>攻击区与碰撞形状不足</strong></td><td>自机持续激光（如魔理沙 B）、命中爆炸（如魔理沙 A 导弹）、旋转矩形与敌人本体接触不能用简单圆弹与穿透次数替代。</td><td>新增 <code>src/core/collision_shapes.py</code>（圆、旋转盒 SAT、曲线段几何）；<code>PlayerBulletPool</code> 扩展锚定激光（<code>fire_laser</code>）、逐目标伤害冷却和命中后阶段变化（<code>ImpactArea</code>）；敌人支持 <code>set_hitbox</code> 与可选 <code>set_contact_hitbox</code>。</td></tr><tr><td><strong>BGM 播放与循环参数未落实</strong></td><td><code>play_bgm</code> 的 <code>loops</code> / <code>start</code> / <code>fade_ms</code> 此前未在音频后端真正落地，也缺少前奏 + 样本级无缝循环点支持。</td><td>新增 <code>src/core/bgm_stream.py</code> 接入 <code>miniaudio</code> 流式混音，支持按源 PCM 帧设置 <code>loop_start_frame</code> / <code>loop_end_frame</code>、<code>loops</code>、<code>start</code>、<code>seek_bgm</code> 与淡入淡出，不整首缓存到内存。</td></tr></tbody></table><p>详细调用写法见 <a href="./STAGE_SCRIPTING_GUIDE">弹幕脚本开发指南</a> 第 10 节。</p><h2 id="_3-无需新增底层机制的部分" tabindex="-1">3. 无需新增底层机制的部分 <a class="header-anchor" href="#_3-无需新增底层机制的部分" aria-label="Permalink to &quot;3. 无需新增底层机制的部分&quot;">​</a></h2><p>以下 TH07 特性可直接基于现有通用接口在内容层组织，无需引入原作虚拟机或第二套运行时：</p><ul><li><strong>常规发射、波次、多角色在场</strong>：使用现有 <code>StageScript</code>、<code>Wave</code>、<code>EnemyScript</code>、<code>SpellCard</code> 和 <code>RunState</code>。</li><li><strong>弹幕分裂、批量改向、沿激光发弹、弹转敌</strong>：使用共享行为阶段表与批量数组接口。</li><li><strong>Cherry / CherryMax / 森罗结界策略</strong>：计分与结界状态属于内容层规则，通过受击钩子与道具收集回调实现。</li><li><strong>3D 场景与离线数据</strong>：将 <code>STD</code> 几何离线烘焙为 <code>SceneQuad</code> 并在普通脚本中控制镜头、雾效和文字，无需运行时 STD/ANM 解释器。</li></ul><h2 id="_4-离线数据分析参考" tabindex="-1">4. 离线数据分析参考 <a class="header-anchor" href="#_4-离线数据分析参考" aria-label="Permalink to &quot;4. 离线数据分析参考&quot;">​</a></h2><p>若需使用用户本机合法拥有的 TH07 副本与 <code>thtk</code> 查看原版 ECL 结构，可在临时目录执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">thdat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l7</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">path-to-th07.da</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">thdat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x7</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">path-to-th07.da</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ecldata5.ecl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ecldata6.ecl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">thecl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ecldata5.ecl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ecldata5.ecl.txt</span></span></code></pre></div><h2 id="_5-后续移植方向" tabindex="-1">5. 后续移植方向 <a class="header-anchor" href="#_5-后续移植方向" aria-label="Permalink to &quot;5. 后续移植方向&quot;">​</a></h2><ul><li>逐面补充关卡内容与多难度核对（五面与六面已作为重点实验完成核心流程，见对应文档）。</li><li>实现六名原版自机配置、高低速 Bomb、完整 CherryMax / 结界计分策略及对话演出（MSG）。</li><li>持续对比原版视觉细节、碰撞精度与真实游玩手感。</li></ul>`,17)])])}const _=t(d,[["render",i]]);export{k as __pageData,_ as default};
